target.css:
:root {
  --green-dark: #2d6a4f;
  --green-mid: #52b788;
  --green-light: #d8f3dc;
  --cream: #fefae0;
  --brown: #7c5e3a;
  --text-dark: #1b2e24;
  --text-muted: #5a7a65;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.badge {
  background-color: var(--cream);
  border: 3px solid var(--green-dark);
  border-radius: 16px;
  width: 300px;
  padding: 0;
  overflow: hidden;
}

.badge-header {
  background-color: var(--green-dark);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 18px;
}

.badge-icon {
  font-size: 22px;
  line-height: 1;
}

.badge-label {
  color: var(--green-light);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.badge-body {
  padding: 18px 18px 14px;
  border-bottom: 2px dashed var(--green-mid);
}

.plant-name {
  margin: 0 0 4px;
  font-size: 20px;
  font-weight: 700;
  color: var(--text-dark);
  line-height: 1.2;
}

.plant-type {
  margin: 0;
  font-size: 13px;
  color: var(--text-muted);
}

.badge-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 18px;
  background-color: var(--green-light);
}

.badge-date {
  font-size: 12px;
  color: var(--brown);
  font-weight: 600;
}

.badge-tag {
  background-color: var(--green-mid);
  color: var(--cream);
  font-size: 12px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
}

